/**
 * The flight data of the event, read frame by frame from the flight data animation the USAF made of it (the video in
 * spec.ts, 640 × 480 at 10 frames a second): the airspeed and altitude needles, the attitude indicator's horizon, the
 * AOA, flap and N1 tapes' markers, and the heading window's digits. The needles were checked against the airspeed and
 * altitude windows' digits and corrected to them where those could be read (readings.ts); SOURCES.md has the method,
 * the calibrations and the limits. Not the recorder's own samples: the animation's, smoothed over about half a second.
 *
 * Every channel has one value each 0.2 s from 7.0 s, in seconds into the video, the cockpit audio's time.
 * Generated from the extraction; change the readings and regenerate rather than editing a number here.
 */

/** Seconds into the video of the first sample; the title cards come before it. */
export const FDR_T0 = 7.0;
/** Seconds between samples. */
export const FDR_DT = 0.2;

export interface FdrChannels {
  /** Indicated airspeed, kt. The animation's airspeed never reads below 50 kt: at 50 the IAS was 50 kt or less. */
  ias: readonly number[];
  /** Altitude, ft, as the animation's altimeter shows it. */
  alt: readonly number[];
  /** Heading, degrees, from the heading window. */
  hdg: readonly number[];
  /** Pitch attitude, degrees, nose up positive. */
  pitch: readonly number[];
  /** Bank, degrees, right wing down positive. */
  bank: readonly number[];
  /** Angle of attack on the animation's AOA tape, which runs from −10 to 30: at 30 it is off the top. */
  aoa: readonly number[];
  /** N1 of engines 1 to 4 (left outboard to right outboard), percent. */
  n1: readonly (readonly number[])[];
  /** Flap position on the animation's flap tape, percent of full travel. */
  flaps: readonly number[];
}

